import java.util.*; public class Solution { public List<String> findItinerary(List<List<String>> tickets) { Map<String, PriorityQueue<String>> adj = new HashMap<>(); for (List<String> ticket : tickets) { adj.computeIfAbsent(ticket.get(0), k -> new PriorityQueue<>()).add(ticket.get(1)); } List<String> itinerary = new ArrayList<>(); dfs("JFK", adj, itinerary); Collections.reverse(itinerary); return itinerary; } private void dfs(String curr, Map<String, PriorityQueue<String>> adj, List<String> itinerary) { PriorityQueue<String> neighbors = adj.get(curr); while (neighbors != null && !neighbors.isEmpty()) { dfs(neighbors.poll(), adj, itinerary); } itinerary.add(curr); } }